def check(label,actual,expected,tol=1e-9):
 assert abs(actual-expected)<=tol*max(1,abs(expected)),(label,actual,expected)
 CHECKS.append({'type':'numerical','check':label,'actual':actual,'expected':expected,'relativeTolerance':tol})
def chemical(note):CHECKS.append({'type':'chemical reasoning','check':note,'passed':True})
def atoms(formula):
 formula=formula.split('^')[0]
 if formula=='e':return {}
 stack=[{}]
 tokens=re.findall(r'[A-Z][a-z]?|\d+|[()]',formula);i=0
 while i<len(tokens):
  token=tokens[i]
  if token=='(':stack.append({});i+=1;continue
  if token==')':
   group=stack.pop();i+=1;mul=int(tokens[i]) if i<len(tokens) and tokens[i].isdigit() else 1
   if i<len(tokens) and tokens[i].isdigit():i+=1
   for a,v in group.items():stack[-1][a]=stack[-1].get(a,0)+mul*v
   continue
  i+=1;mul=int(tokens[i]) if i<len(tokens) and tokens[i].isdigit() else 1
  if i<len(tokens) and tokens[i].isdigit():i+=1
  stack[-1][token]=stack[-1].get(token,0)+mul
 return stack[0]
def charge(formula):
 if '^' not in formula:return 0
 q=formula.split('^')[1];return (-1 if q.endswith('-') else 1)*int(q[:-1] or 1)
def balanced(left,right):
 def totals(side):
  total={};q=0
  for species,n in side.items():
   q+=charge(species)*n
   for a,v in atoms(species).items():total[a]=total.get(a,0)+v*n
  return {a:v for a,v in total.items() if v},q
 assert totals(left)==totals(right),(left,right,totals(left),totals(right))
 CHECKS.append({'type':'atom/charge balance','left':left,'right':right,'totals':totals(left)})
def text(x,y,t,size=14,anchor='middle'):
 return f'<text x="{x:.2f}" y="{y:.2f}" font-family="Arial,sans-serif" font-size="{size}" text-anchor="{anchor}" fill="#111" stroke="none">{escape(str(t))}</text>'
def svg(body,title):
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 680 420" role="img"><title>'+escape(title)+'</title><rect width="680" height="420" fill="white"/><g fill="none" stroke="#111" stroke-width="1.7">'+body+'</g></svg>'
def line(x,y,u,v,dash=False):return f'<path d="M{x:.2f} {y:.2f}L{u:.2f} {v:.2f}"'+(' stroke-dasharray="7 4"' if dash else '')+'/>'
def arrow(x,y,u,v,label=''):
 dx=u-x;dy=v-y;mag=math.hypot(dx,dy);a=dx/mag;b=dy/mag
 return line(x,y,u,v)+line(u-8*a+4*b,v-8*b-4*a,u,v)+line(u-8*a-4*b,v-8*b+4*a,u,v)+(text((x+u)/2+12,(y+v)/2-7,label,13) if label else '')
def graph(fs,box,xlab,ylab,points=(),labels=(),title='Constructed data/model graph',horiz=()):
 xa,xb,ya,yb=box;X=lambda x:80+520*(x-xa)/(xb-xa);Y=lambda y:340-260*(y-ya)/(yb-ya)
 body=text(65,30,title,15,'start')+line(80,65,80,340)+line(80,340,610,340)+text(340,401,xlab,14)+text(80,53,ylab,13,'start')
 for i in range(6):
  x=xa+(xb-xa)*i/5;y=ya+(yb-ya)*i/5
  body+=line(X(x),340,X(x),346)+text(X(x),368,f'{x:.3g}',11)+line(74,Y(y),80,Y(y))+text(65,Y(y)+4,f'{y:.3g}',11,'end')
 for i,f in enumerate(fs):
  chunks=[];pts=[]
  for j in range(241):
   x=xa+(xb-xa)*j/240
   try:y=f(x)
   except (ZeroDivisionError,ValueError,OverflowError):y=float('nan')
   if math.isfinite(y) and ya<=y<=yb:pts.append((X(x),Y(y)))
   elif pts:chunks.append(pts);pts=[]
  if pts:chunks.append(pts)
  for pts in chunks:
   body+='<polyline points="'+' '.join(f'{x:.2f},{y:.2f}' for x,y in pts)+'"'+(' stroke-dasharray="7 4"' if i%2 else '')+'/>'
  if i<len(labels):body+=text(410,53+i*18,labels[i],12,'start')
 for x,y,label in points:body+=f'<circle cx="{X(x):.2f}" cy="{Y(y):.2f}" r="3.3" fill="#111"/>'+text(X(x)+5,Y(y)-9,label,12,'start')
 for value,label in horiz:body+=line(80,Y(value),600,Y(value),True)+text(605,Y(value)-4,label,12,'end')
 return svg(body,title)
def profile(levels,labels,title='Potential-energy profile; exact levels supplied'):
 # Smooth interpolation between exact stationary levels; coordinate is not time.
 def f(x):
  j=min(len(levels)-2,int(x));u=x-j
  return levels[j]+(levels[j+1]-levels[j])*(3*u*u-2*u*u*u)
 lo=min(levels)-15;hi=max(levels)+20
 pts=[(i,v,label) for i,(v,label) in enumerate(zip(levels,labels))]
 return graph([f],(0,len(levels)-1,lo,hi),'reaction coordinate','potential energy / kJ mol^-1',pts,title=title)
def energy_path(levels):
 def f(x):
  j=min(len(levels)-2,int(x));u=x-j
  return levels[j]+(levels[j+1]-levels[j])*(3*u*u-2*u*u*u)
 return f
def cycle(states,ys,links,title='Energy cycle; arrows are supplied processes'):
 axislabel='Gibbs energy (schematic)' if 'Gibbs' in title else 'enthalpy (schematic)'
 body=text(35,28,title,15,'start')+arrow(60,350,60,65)+text(75,53,axislabel,13,'start')
 xs=[200,450,450,200,330,560][:len(states)]
 for i,(state,y) in enumerate(zip(states,ys)):
  body+=line(xs[i]-65,y,xs[i]+65,y)+text(xs[i],y-12,state,13)
 for a,b,label in links:body+=arrow(xs[a],ys[a]+8,xs[b],ys[b]-8,label)
 return svg(body,title)
def bars(names,values,ylabel,title='Supplied comparison data'):
 mx=max(values)*1.15;body=text(35,28,title,15,'start')+line(75,60,75,340)+line(75,340,615,340)+text(80,53,ylabel,13,'start')
 for i,(name,v) in enumerate(zip(names,values)):
  x=140+i*440/max(1,len(names)-1);h=250*v/mx
  body+=f'<rect x="{x-24:.2f}" y="{340-h:.2f}" width="48" height="{h:.2f}" fill="#f0f0f0"/>'+text(x,365,name,13)+text(x,330-h,f'{v:.4g}',13)
 for i in range(6):body+=text(65,344-i*50,f'{mx*i/5:.3g}',11,'end')
 return svg(body,title)
