 marks=sum(p['marks'] for p in ps);assert 8<=marks<=14,(ident,marks)
 q={'id':ident,'subject':'chemistry','topicId':theme,'collectionId':'chemistry-'+theme,'number':num,'title':title,'subtopic':TITLES[code],'syllabusCode':code,'level':level,'difficulty':'hard','calculator':True,'questionType':'data-based','marks':marks,'stem':stem+' Give calculated answers to three significant figures unless a different precision is requested.','parts':ps,'markScheme':ms,'diagramSvg':diagram,'diagramCaption':'Original vector diagram. Experimental readings are constructed for this question; energy profiles are schematic in reaction coordinate, with supplied vertical levels.','answerSummary':summary,'source':{'document':'Independent syllabus-authored practice','question':num},'verification':{'method':'Question-specific atom/charge, dimensional, chemical-reasoning and independent numerical checks','notes':'All author checks are recorded per ID in the reactivity author review; accept chemically correct alternative methods and consistent error carried forward. Independent review is required before release.'},'status':'published'}
 Q.append(q);AUDIT.append({'id':ident,'checks':list(CHECKS),'scope':level+'; '+code});CHECKS.clear()

