def polished(value):
 # Chemical formulae and unit symbols are protected before normal prose is
 # spaced. This deliberately avoids changing case/digits inside any formula.
 superscripts=str.maketrans('-0123456789','⁻⁰¹²³⁴⁵⁶⁷⁸⁹')
 value=re.sub(r'(?<![A-Za-z])(\d+(?:\.\d+)?)[eE]([+-]?\d+)',lambda m:m.group(1)+'×10'+str(int(m.group(2))).translate(superscripts),value)
 for a,b in [('moldm','mol dm'),('kJmol','kJ mol'),('Jmol','J mol'),('gmol','g mol'),('dm³mol','dm³ mol'),('mols⁻¹','mol s⁻¹'),('JK⁻¹','J K⁻¹'),('Jg⁻¹','J g⁻¹'),('K⁻¹mol','K⁻¹ mol'),('molof','mol of'),('moleach','mol each'),('molper','mol per'),('molgraphite','mol graphite'),('molethanol','mol ethanol'),('molacid','mol acid'),('molreaction','mol reaction')]:value=value.replace(a,b)
 protected=['CH₃COOC₂H₅','CH₃COOH','C₂H₅OH','H₂O₂','C₂H₄','C₂H₆','CH₃OH','CH₄','CaCO₃','CaCl₂','MgCO₃','Al₂(SO₄)₃','CuSO₄','AgNO₃','AgCl','NaNO₃','N₂O₄','N₂O₂','NO₂','NO₃','NOBr','Br₂','COCl₂','Cl₂','ICl','HCl','H₂O','CO₂','H₂','O₂','N₂','NH₃','I₂','HI','NO','CO','MgCl₂','MgO','Na₂O','NaCl','NaOH','Na⁺','Cl⁻','Mg²⁺','O²⁻','O⁻','OH⁻','H⁺','Cu²⁺','Ag⁺','kJ','KAB','KBC','KAC','Kfast','Ea','ΔH','ΔS','ΔG','ECF','TS1','TS2','NO2','NO3','CO2','COCl2','N2O4','N2O2','NH3','H2O2','H2O','H2','O2','N2','Br2','Cl2','CH4','C2H6','C2H4','CH3OH','MgCl2','AB₂','AB2','AB']
 protected += ['ΔHf°','ΔHc°','ΔHlatt','ΔSsurroundings','ΔSsystem','ΔStotal']
 tokens={}
 for token in sorted(set(protected),key=len,reverse=True):
  if token in value:
   marker=chr(0xE000+len(tokens));value=value.replace(token,marker);tokens[marker]=token
 # Number-unit and prose-variable boundaries; PUA markers isolate formulae.
 value=re.sub(r'(?<=[0-9⁰¹²³⁴⁵⁶⁷⁸⁹])(?=[A-Za-z])',' ',value)
 value=re.sub(r'(?<=[a-z])(?=[0-9])',' ',value)
 value=re.sub(r'(?<=[a-z])(?=[A-Z])',' ',value)
 value=re.sub(r'(?<=[A-Za-z0-9⁰¹²³⁴⁵⁶⁷⁸⁹])(?=[\uE000-\uE0FF])',' ',value)
 value=re.sub(r'(?<=[\uE000-\uE0FF])(?=[A-Za-z])',' ',value)
 for a,b in [('andv','and v'),('quadruplesv','quadruples v'),('vby','v by'),('unchangedv','unchanged v'),('khas','k has'),('kand','k and'),('kwith','k with'),('kfor','k for'),('Aand','A and'),('Band','B and'),('Cand','C and'),('Mand','M and'),('Kand','K and'),('Qand','Q and'),('Tand','T and'),('Ais','A is'),('Bis','B is'),('Cis','C is'),('Mis','M is'),('Kis','K is'),('Qis','Q is'),('Tis','T is'),('Awas','A was'),('Qbecomes','Q becomes'),('Premains','P remains'),('Qdoes','Q does'),('Qto','Q to'),('Pat','P at'),('Qat','Q at'),('Bshare','B share'),('Cshare','C share'),('A⇌Bhas','A⇌B has'),('B⇌Chas','B⇌C has'),('forA','for A'),('ofA','of A'),('asA','as A'),('fromA','from A'),('forB','for B'),('ofB','of B'),('forC','for C'),('ofC','of C'),('theNO','the NO'),('ownk','own k'),('largerk','larger k'),('smallerk','smaller k'),('temperatureT','temperature T'),('fractionx','fraction x'),('extentx','extent x'),('timeT','time T'),('throughoutT','throughout T')]:value=value.replace(a,b)
 common='is|has|have|are|and|or|only|does|do|increases|decreases|remains|unchanged|consumed|reacts|instantaneously|depletion|at|in|of|to|by|for|with|then|cannot|can|from|gives|becomes|formation|per|applies|the|should|would|fits|against|were|being|as|constant|alone|relation'
 value=re.sub(r'\b([ABCPQKTMVXYxvkn])(?=(?:'+common+r')(?:\b|[A-Z\uE000-\uE0FF]))',r'\1 ',value)
 value=value.replace('Letx','Let x').replace('letx','let x').replace('subtractxfrom','subtract x from').replace('ofx','of x').replace('Kforward','K forward').replace('Kreverse','K reverse').replace('RTln','RT ln').replace('multipliesv','multiplies v').replace('givingx','giving x').replace('whenb','when b').replace(')against',') against').replace('1/Tplot','1/T plot').replace('leavesvunchanged','leaves v unchanged').replace('Tgivev','T give v').replace('ofx','of x').replace('Bhave','B have').replace('A–Crelation','A–C relation')
 value=re.sub(r'\bA(?=\d)','A ',value)
 value=re.sub(r'(?<=[⁰¹²³⁴⁵⁶⁷⁸⁹])(?=(?:mol|s|K|J|g|cm|dm)\b)',' ',value)
 value=re.sub(r'%(?=[A-Za-z])','% ',value)
 value=re.sub(r'(?<=[a-z])(?=\[)',' ',value)
 value=re.sub(r'\](?=[a-z])','] ',value)
 value=re.sub(r'\)(?=(?:and|at|is|are|M|in|by|for|with|from)\b)',') ',value)
 value=re.sub(r'[,;](?=\S)',lambda m:m.group()+' ',value)
 value=re.sub(r'\s*([=→⇌+])\s*',r' \1 ',value)
 value=re.sub(r'\s+',' ',value).strip()
 for marker,token in tokens.items():value=value.replace(marker,token)
 return value

